
import type { SubscriptionServiceLocationInput } from './SubscriptionServiceLocationInput.js';

export type SubscriptionInput = { "awaiting_billing_schedule"?: never; /** Format: int32. */ "billing_anchor_day"?: number; /** How often the subscription bills, frozen when the subscription was created. Read with billing_interval_count: monthly with a count of 3 bills quarterly. Omitted for subscriptions created before Flint recorded this interval. */ "billing_interval"?: never; /** Number of billing_interval units between charges, frozen when the subscription was created. Omitted for subscriptions created before Flint recorded this interval. Format: int32. */ "billing_interval_count"?: never; "billing_schedule_owner"?: never; /** RFC3339 timestamp. Format: date-time. */ "billing_schedule_waiting_started_at"?: never; /** What the buyer can do with the subscription, in this order: cancel, pause, resume, reactivate, update_payment_method, then retry_payment, under the store's customer_account.buyer_capabilities. A buyer's read or change through a customer session on /v1/me, or in Flint's buyer account, lists all six every time; a merchant read gets an empty list. update_payment_method is required while a payment is past due, due by next_retry_at when a retry is scheduled, and when the card expires before next_billing_at, due by then. Example: []. */ "buyer_actions"?: never; /** True when the subscription is scheduled to cancel at the end of the current period. Schedule with the cancel route and undo with the reactivate route. */ "cancel_at_period_end"?: never; /** RFC3339 timestamp. Format: date-time. */ "canceled_at"?: never; /** Who asked to cancel, when, and why. Present once a cancellation is requested, whether it takes effect at the end of the billing period or right away. Omitted when no one asked, such as a cancellation after failed payments, and removed when a scheduled cancellation is undone. */ "cancellation_details"?: never; /** RFC3339 timestamp. Format: date-time. */ "contract_end_at"?: never; /** RFC3339 timestamp. Format: date-time. */ "contract_start_at"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "current_period_end"?: never; "current_period_start"?: never; "customer"?: never; "customer_id": string; /** Early termination fee frozen in the subscription's contract terms. Present only before contract_end_at when those terms include a fee. Later plan changes do not change this fee. */ "early_termination_fee_money"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "line_items"?: never; "merchant_id"?: never; "metadata"?: Record<string, string>; /** RFC3339 timestamp. Format: date-time. */ "next_billing_at"?: never; /** Recorded automatic payment retry time. Null when no retry time is available. Format: date-time. */ "next_retry_at"?: never; /** RFC3339 timestamp. Format: date-time. */ "paused_at"?: never; "payment_method"?: never; "payment_method_id": string; /** What one billing period charges before tax and discounts, frozen when the subscription was created. Plan price changes after that do not change it. Omitted for subscriptions created before Flint recorded this amount. */ "recurring_amount_money"?: never; /** Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "service_location"?: SubscriptionServiceLocationInput; /** RFC3339 timestamp. Format: date-time. */ "starts_at"?: never; "status"?: never; "subscription_id"?: never; "subscription_plan"?: never; "subscription_plan_id": string; "trial_end"?: never; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; };
